    # exceeds warn_factor (default 10×).
    "tx_bit_width_min_resolution_check",
    # v0.119.27 LL-28 was REMOVED in v0.119.29: the prescribed QSF form
    # `set_instance_assignment -name OPEN_DRAIN ON -to <pad>` causes
