    # — only applicable to Path A (NL prompt → L docs); FAILs cleanly
    # on Path B projects that ran phase1 from input/docs.
    "phase1_k5_quality_check",
    "phase1_quality_parity_check",
    "rtl_precheck_gate",
    "scope_periodic_pulse_check",
